let data;

try {
    data = JSON.parse(msg.payload.value);
} catch (err) {
    node.error("Could not parse ECG value: " + err.message, msg);
    return null;
}

let leads = data.leads;

if (!leads) {
    node.error("No leads found in ECG data", msg);
    return null;
}

node.warn("LEADS: " + Object.keys(leads).join(", "));


// Process every lead that exists
for (let leadName of Object.keys(leads)) {

    let samples = leads[leadName];

    // We expect an array of ECG samples
    if (!Array.isArray(samples)) {
        node.warn("Skipping " + leadName + " - not an array");
        continue;
    }

    node.warn(
        "Processing " + leadName +
        " | samples: " + samples.length
    );


    // Send every ECG sample as one InfluxDB point
    for (let i = 0; i < samples.length; i++) {

        let value = Number(samples[i]);

        if (!Number.isFinite(value)) {
            continue;
        }

        let outMsg = {
            payload: [
                {
                    value: value
                },
                {
                    lead: leadName
                }
            ]
        };

        node.send(outMsg);
    }
}

return null;
